        age = int(age)
        if age > 0:
            return name, age
        else:
            print("Error: Age must be a positive integer. Please try again.")
    except ValueError:
        print("Error: Age must be a number. Please try again.")

def greet_user(name, age):
    print(f"Hello, {name}! You are {age} years old.")

name, age = get_valid_input()
greet_user(name, age)
